package rtmp

import (
	"encoding/hex"
	"testing"
)

// nativeVideoFixture возвращает literal headers и два исходных AU синтетических CPU-кодировщиков.
// HEVC/H.264 сохраняют полный выход PQ Main10/high10 FFmpeg7.1.5; VP9 record явно задаёт BT.709
// поверх проверенного coarse BT.709 кадра. Это не проверка сохранности native CICP FFmpeg у VP9.
func nativeVideoFixture(t *testing.T, kind string) ([]byte, []byte, []byte) {
	t.Helper()
	// raw содержит ограниченные hex-образцы без обращения к временным или пользовательским файлам.
	var raw [3]string
	switch kind {
	case "hevc":
		raw = [3]string{"", "", ""}
	case "h264":
		raw = [3]string{"016e000affe1001c676e000aa6cb41023602d4244025000003000100000300180f1226a001000468ce0fc8fdfafa00", "", ""}
	case "vp9":
		raw = [3]string{"000a820101010000", "824983424003f003f60038241c184a00003060000078b9ffff57b0ffffff7c17fffffffc78c1cfd2e880", "860040929c00500000036000005470"}
	default:
		t.Fatal("Неизвестный codec fixture", kind)
	}
	// decoded хранит отдельные неизменяемые копии headers и двух AU.
	var decoded [3][]byte
	// index и encoded выбирают три literal buffers в их исходном порядке.
	for index, encoded := range raw {
		// err сообщает о случайном повреждении hex-записи fixture.
		var err error
		decoded[index], err = hex.DecodeString(encoded)
		if err != nil {
			t.Fatal(err)
		}
	}
	return decoded[0], decoded[1], decoded[2]
}
